@js:
try {
function x(bytes, key, iv) {
	return java.createSymmetricCrypto(
	"aes/cbc/ZeroPadding", 
	 java.strToBytes(key),
	 java.base64DecodeToByteArray(iv)
	)
.decryptStr(java.base64DecodeToByteArray(bytes))
}


eval(result.match(/\$\('#booktxthtml'\).html\(([^)]+\))/)[1])
} catch(e) {
	e + "<br>" + result
}

