ruleContent.content:
@js:(function(){
  var st = fqS(String(result));
  var cd = fqG(fqG(st, "reader"), "chapterData");
  var c = fqD(String(fqG(cd, "content")));
  var imgs = [];
  c = c.replace(/<img[^>]*?(\{[^{}]*"web_uri"[^{}]*\})[^>]*>/gi, function (m, js) {
    var o = null;
    try { o = JSON.parse(js); } catch (e) { return ""; }
    var uri = fqG(o, "web_uri");
    if (uri === "") { return ""; }
    imgs.push("https://p6-novel.byteimg.com/" + uri + "~tplv-resize:" +
              fqG(o, "width") + ":" + fqG(o, "height") + ".image");
    return "\u0001" + (imgs.length - 1) + "\u0001";
  });
  c = c.replace(/<\/p>\s*<p>/gi, "\n");
  c = c.replace(/<br\s*\/?>/gi, "\n");
  c = c.replace(/<\/?p[^>]*>/gi, "\n");
  c = c.replace(/<\/img>/gi, "");
  c = c.replace(/<[^>]+>/g, "");
  c = c.replace(/&nbsp;/g, " ");
  c = c.replace(/&lt;/g, "<");
  c = c.replace(/&gt;/g, ">");
  c = c.replace(/&quot;/g, '"');
  c = c.replace(/&#39;/g, "'");
  c = c.replace(/&amp;/g, "&");
  c = c.replace(/\r/g, "");
  c = c.replace(/[ \t]+\n/g, "\n");
  c = c.replace(/\n{3,}/g, "\n\n");
  c = c.replace(/\u0001(\d+)\u0001/g, function (m, i) {
    return "\n<img src=\"" + imgs[Number(i)] + "\">\n";
  });
  return c.replace(/^\s+|\s+$/g, "");
})()

ruleToc.chapterList:
@js:(function(){
  var d = fqG(JSON.parse(String(result)), "data");
  var out = [];
  var cv = fqG(d, "chapterListWithVolume");
  var vn = fqG(d, "volumeNameList");
  var i, j, g, c, nm;
  if (cv !== "" && cv !== null) {
    for (i = 0; i < cv.length; i++) {
      g = cv[i];
      if (g === null || g === undefined) { continue; }
      if (g.length === 0) { continue; }
      if (cv.length > 1) {
        nm = "";
        if (vn !== "" && vn !== null) { if (vn[i] !== undefined) { nm = String(vn[i]); } }
        out.push(JSON.stringify({n: nm, u: "", v: true, t: "共" + g.length + "章"}));
      }
      for (j = 0; j < g.length; j++) {
        c = g[j];
        out.push(JSON.stringify({
          n: fqD(String(fqG(c, "title"))),
          u: "https://fanqienovel.com/reader/" + fqG(c, "itemId"),
          v: false,
          t: fqG(c, "firstPassTime"),
          p: fqG(c, "needPay"),
          x: fqG(c, "isChapterLock")
        }));
      }
    }
  }
  if (out.length === 0) {
    var ids = fqG(d, "allItemIds");
    for (i = 0; i < ids.length; i++) {
      out.push(JSON.stringify({n: "第" + (i + 1) + "章",
                               u: "https://fanqienovel.com/reader/" + ids[i], v: false}));
    }
  }
  return out;
})()

